import json
import csv
import os
import itertools
from copy import deepcopy

# ============================================================
# PROBLEM DATA
# ============================================================

NUM_JOBS = 4
NUM_MACHINES = 3

# operations[job][op] = list of (machine, duration) alternatives
operations = {
    0: {
        0: [(0, 6), (1, 5)],
        1: [(1, 7), (2, 6)],
        2: [(0, 5), (2, 8)],
    },
    1: {
        0: [(0, 5), (2, 7)],
        1: [(1, 6), (2, 5)],
        2: [(0, 7), (1, 8)],
    },
    2: {
        0: [(1, 4), (2, 6)],
        1: [(0, 8), (1, 7)],
        2: [(0, 6), (2, 5)],
    },
    3: {
        0: [(0, 7), (1, 6)],
        1: [(1, 5), (2, 7)],
        2: [(0, 4), (2, 6)],
    },
}

# Downtime windows: machine -> list of (start, end)
downtime = {
    0: [],
    1: [(5, 20)],
    2: [(12, 25)],
}

# Baseline schedule
baseline = [
    {"job": 1, "op": 0, "machine": 0, "start": 0, "end": 5, "dur": 5},
    {"job": 0, "op": 0, "machine": 1, "start": 0, "end": 5, "dur": 5},
