FREEZE_UNTIL = 6
MAX_MACHINE_CHANGES = 4
MAX_L1_SHIFT = 120
MAX_MAKESPAN = 39  # floor(36 * 1.1) = 39

# Frozen operations: those with end <= FREEZE_UNTIL in baseline
frozen = set()
for entry in baseline:
    if entry["end"] <= FREEZE_UNTIL:
        frozen.add((entry["job"], entry["op"]))

print(f"Frozen operations: {frozen}")


def overlaps_downtime(machine, start, end):
    """Check if [start, end) overlaps with any downtime on machine."""
    for ds, de in downtime.get(machine, []):
        if start < de and end > ds:
            return True
    return False


def earliest_start_on_machine(machine, earliest, duration):
    """Find earliest start >= earliest on machine avoiding downtime."""
    start = earliest
    for ds, de in sorted(downtime.get(machine, [])):
        if start < de and start + duration > ds:
            # Overlaps downtime, push start to after downtime
            start = de
    return start


def get_duration(job, op, machine):
    """Get duration for a specific (job, op, machine) combination."""
    for m, d in operations[job][op]:
        if m == machine:
            return d
    return None


def validate_schedule(schedule):
    """Validate a schedule against all constraints. Returns (valid, issues)."""
    issues = []

    # 1. Check frozen operations
    for entry in schedule:
        key = (entry["job"], entry["op"])
        if key in frozen:
            bl = baseline_lookup[key]
            if entry["machine"] != bl["machine"] or entry["start"] != bl["start"] or entry["end"] != bl["end"]:
                issues.append(f"Frozen operation {key} was modified")

    # 2. Check downtime violations
    violations = 0
    for entry in schedule:
        if overlaps_downtime(entry["machine"], entry["start"], entry["end"]):
            violations += 1
            issues.append(f"Downtime violation: Job {entry['job']} Op {entry['op']} on M{entry['machine']} [{entry['start']},{entry['end']}]")

    # 3. Check precedence constraints (within each job)
    job_ops = {}
    for entry in schedule:
        job_ops.setdefault(entry["job"], {})[entry["op"]] = entry
    for job in range(NUM_JOBS):
