best_schedule, best_makespan, best_mc, best_l1 = try_all_machine_assignments()

# Also try with different priority rules
print("\n--- Trying priority rules ---")
flexible_ops_list = []
machine_options_dict = {}
for job in range(NUM_JOBS):
    for op in range(3):
        if (job, op) in frozen:
            continue
        options = [m for m, d in operations[job][op]]
        machine_options_dict[(job, op)] = options
        flexible_ops_list.append((job, op))

all_opts = [machine_options_dict[key] for key in flexible_ops_list]

for priority in ["SPT", "EST", "LPT"]:
    for combo in itertools.product(*all_opts):
        machine_choices = {}
        for key in frozen:
            machine_choices[key] = baseline_lookup[key]["machine"]
        for i, key in enumerate(flexible_ops_list):
