    print(f"{'=' * 60}")
    print(f"Makespan: {best_makespan}")
    print(f"Machine changes: {best_mc}")
    print(f"L1 start shift: {best_l1}")

    # Final validation
    valid, issues, makespan, mc, l1 = validate_schedule(best_schedule)
    print(f"\nValidation: {'PASS' if valid else 'FAIL'}")
    if issues:
        for issue in issues:
            print(f"  - {issue}")

    # Print schedule
    print(f"\nSchedule:")
    for entry in sorted(best_schedule, key=lambda x: (x["start"], x["job"])):
        bl = baseline_lookup[(entry["job"], entry["op"])]
        mc_flag = " (MC)" if entry["machine"] != bl["machine"] else ""
        fr_flag = " (FROZEN)" if (entry["job"], entry["op"]) in frozen else ""
        print(f"  Job {entry['job']} Op {entry['op']} -> M{entry['machine']} [{entry['start']:3d}, {entry['end']:3d}] dur={entry['dur']}{mc_flag}{fr_flag}")

    # Print machine Gantt
    print(f"\nMachine Gantt:")
    for m in range(NUM_MACHINES):
        tasks = [e for e in best_schedule if e["machine"] == m]
        tasks.sort(key=lambda x: x["start"])
        desc = " -> ".join(f"J{e['job']}O{e['op']}[{e['start']}-{e['end']}]" for e in tasks)
        dt_str = f" (down {downtime[m]})" if downtime[m] else ""
        print(f"  M{m}{dt_str}: {desc}")

    # Write output
    os.makedirs("/app/output", exist_ok=True)

    solution = {
        "status": "FEASIBLE",
        "makespan": best_makespan,
        "schedule": sorted(best_schedule, key=lambda x: (x["start"], x["job"]))
    }

    with open("/app/output/solution.json", "w") as f:
        json.dump(solution, f, indent=2)

    with open("/app/output/schedule.csv", "w", newline="") as f:
        writer = csv.DictWriter(f, fieldnames=["job", "op", "machine", "start", "end", "dur"])
        writer.writeheader()
        for entry in sorted(best_schedule, key=lambda x: (x["start"], x["job"])):
            writer.writerow(entry)

    print(f"\nOutput written to /app/output/solution.json and /app/output/schedule.csv")
else:
    print("NO FEASIBLE SOLUTION FOUND")

