                issues.append(f"Frozen operation {key} was modified")

    # 2. Check downtime violations
    violations = 0
    for entry in schedule:
        if overlaps_downtime(entry["machine"], entry["start"], entry["end"]):
            violations += 1
            issues.append(f"Downtime violation: Job {entry['job']} Op {entry['op']} on M{entry['machine']} [{entry['start']},{entry['end']}]")

    # 3. Check precedence constraints (within each job)
    job_ops = {}
    for entry in schedule:
        job_ops.setdefault(entry["job"], {})[entry["op"]] = entry
    for job in range(NUM_JOBS):
        for op in range(1, 3):
            if job_ops[job][op]["start"] < job_ops[job][op - 1]["end"]:
                issues.append(f"Precedence violation: Job {job} Op {op} starts at {job_ops[job][op]['start']} before Op {op-1} ends at {job_ops[job][op-1]['end']}")

    # 4. Check machine non-overlap
    machine_tasks = {}
    for entry in schedule:
        machine_tasks.setdefault(entry["machine"], []).append(entry)
    for m, tasks in machine_tasks.items():
        tasks_sorted = sorted(tasks, key=lambda x: x["start"])
        for i in range(len(tasks_sorted) - 1):
            if tasks_sorted[i]["end"] > tasks_sorted[i + 1]["start"]:
                issues.append(f"Machine overlap: M{m} - Job {tasks_sorted[i]['job']} Op {tasks_sorted[i]['op']} [{tasks_sorted[i]['start']},{tasks_sorted[i]['end']}] overlaps Job {tasks_sorted[i+1]['job']} Op {tasks_sorted[i+1]['op']} [{tasks_sorted[i+1]['start']},{tasks_sorted[i+1]['end']}]")

    # 5. Check duration correctness
    for entry in schedule:
        expected_dur = get_duration(entry["job"], entry["op"], entry["machine"])
        if expected_dur is None:
            issues.append(f"Invalid machine assignment: Job {entry['job']} Op {entry['op']} cannot run on M{entry['machine']}")
        elif entry["dur"] != expected_dur:
            issues.append(f"Duration mismatch: Job {entry['job']} Op {entry['op']} on M{entry['machine']} should be {expected_dur} not {entry['dur']}")
        if entry["end"] - entry["start"] != entry["dur"]:
            issues.append(f"Start/End/Dur inconsistency: Job {entry['job']} Op {entry['op']}")

    # 6. Check makespan
    makespan = max(e["end"] for e in schedule)
    if makespan > MAX_MAKESPAN:
        issues.append(f"Makespan {makespan} exceeds max {MAX_MAKESPAN}")

    # 7. Check policy budgets
    machine_changes = 0
    total_l1_shift = 0
    for entry in schedule:
        key = (entry["job"], entry["op"])
        bl = baseline_lookup[key]
        if entry["machine"] != bl["machine"]:
            machine_changes += 1
        total_l1_shift += abs(entry["start"] - bl["start"])

    if machine_changes > MAX_MACHINE_CHANGES:
        issues.append(f"Machine changes {machine_changes} exceeds max {MAX_MACHINE_CHANGES}")
    if total_l1_shift > MAX_L1_SHIFT:
        issues.append(f"L1 start shift {total_l1_shift} exceeds max {MAX_L1_SHIFT}")

    # 8. Check all 12 operations present
    if len(schedule) != 12:
        issues.append(f"Expected 12 operations, got {len(schedule)}")

    return len(issues) == 0, issues, makespan, machine_changes, total_l1_shift


def schedule_greedy(machine_choices):
    """
    Given machine choices for each (job, op), build a schedule using
    earliest-start greedy approach.

    machine_choices: dict of (job, op) -> machine
    Returns: list of schedule entries or None if infeasible
    """
    # Calculate durations
    dur = {}
    for job in range(NUM_JOBS):
        for op in range(3):
            m = machine_choices[(job, op)]
            d = get_duration(job, op, m)
            if d is None:
                return None
            dur[(job, op)] = d

    # Use a list-scheduling approach
    # Track: job_end[job] = end time of last scheduled op for this job
    # machine_end[machine] = list of (start, end) intervals scheduled

    job_next_op = {j: 0 for j in range(NUM_JOBS)}
    job_end = {j: 0 for j in range(NUM_JOBS)}
    machine_intervals = {m: [] for m in range(NUM_MACHINES)}

    schedule = []

    # First, place frozen operations
    for key in frozen:
        job, op = key
        bl = baseline_lookup[key]
        entry = {
            "job": job, "op": op, "machine": bl["machine"],
            "start": bl["start"], "end": bl["end"], "dur": bl["dur"]
        }
        schedule.append(entry)
        machine_intervals[bl["machine"]].append((bl["start"], bl["end"]))
        job_end[job] = max(job_end[job], bl["end"])
        job_next_op[job] = max(job_next_op[job], op + 1)

    # Sort machine intervals
    for m in machine_intervals:
        machine_intervals[m].sort()

    # Iteratively schedule remaining operations
    scheduled = set(frozen)
    max_iters = 100
    iteration = 0

    while len(scheduled) < 12 and iteration < max_iters:
        iteration += 1
        progress = False

        # Find all ready operations (predecessor done or first op)
        ready = []
        for job in range(NUM_JOBS):
            for op in range(3):
                if (job, op) in scheduled:
                    continue
                if op == 0 or (job, op - 1) in scheduled:
                    ready.append((job, op))

        if not ready:
            break

        # Schedule the one with earliest possible start
        best = None
        best_start = float('inf')

        for job, op in ready:
            m = machine_choices[(job, op)]
            d = dur[(job, op)]

            # Earliest from precedence
            earliest = job_end[job] if op > 0 and (job, op - 1) in scheduled else 0
            if op > 0:
                # Find the end time of the previous op
                for e in schedule:
                    if e["job"] == job and e["op"] == op - 1:
                        earliest = e["end"]
                        break

            # Find earliest slot on machine avoiding downtime and other tasks
            start = find_earliest_slot(m, earliest, d, machine_intervals[m])

            if start < best_start:
                best_start = start
                best = (job, op, m, d, start)

        if best is None:
            break

        job, op, m, d, start = best
        end = start + d
        entry = {"job": job, "op": op, "machine": m, "start": start, "end": end, "dur": d}
        schedule.append(entry)
        machine_intervals[m].append((start, end))
        machine_intervals[m].sort()
        scheduled.add((job, op))
        job_end[job] = max(job_end[job], end)
        progress = True

    if len(scheduled) != 12:
        return None

    return schedule


def find_earliest_slot(machine, earliest, duration, existing_intervals):
    """Find earliest start time on machine >= earliest, avoiding downtime and existing tasks."""
    start = earliest

    # Iterate to find a valid slot
    for _ in range(100):
        end = start + duration

        # Check downtime
        dt_conflict = False
        for ds, de in downtime.get(machine, []):
            if start < de and end > ds:
                start = de
                dt_conflict = True
                break
        if dt_conflict:
            continue

        # Check existing intervals
        interval_conflict = False
        for es, ee in sorted(existing_intervals):
            if start < ee and end > es:
                start = ee
                interval_conflict = True
                break
        if interval_conflict:
            continue

        return start

    return start


def try_all_machine_assignments():
    """Try all possible machine assignments and find best feasible schedule."""

    # For each non-frozen (job, op), get list of possible machines
    flexible_ops = []
    machine_options = {}
    for job in range(NUM_JOBS):
        for op in range(3):
            if (job, op) in frozen:
                continue
            options = [m for m, d in operations[job][op]]
            machine_options[(job, op)] = options
            flexible_ops.append((job, op))

    print(f"\nFlexible operations: {len(flexible_ops)}")
    print(f"Total combinations: {2**len(flexible_ops)}")

    best_schedule = None
    best_makespan = float('inf')
    best_mc = 0
    best_l1 = 0
    count = 0
    feasible_count = 0

    # Generate all combinations
    all_options = [machine_options[key] for key in flexible_ops]

    for combo in itertools.product(*all_options):
        count += 1

        # Build machine choices
        machine_choices = {}
        for key in frozen:
            machine_choices[key] = baseline_lookup[key]["machine"]

        for i, key in enumerate(flexible_ops):
            machine_choices[key] = combo[i]

        # Check machine change budget early
        mc = sum(1 for key in flexible_ops if machine_choices[key] != baseline_lookup[key]["machine"])
        if mc > MAX_MACHINE_CHANGES:
            continue

        # Build schedule
        sched = schedule_greedy(machine_choices)
        if sched is None:
            continue

        valid, issues, makespan, machine_changes, l1_shift = validate_schedule(sched)

        if valid and makespan < best_makespan:
            best_schedule = sched
            best_makespan = makespan
            best_mc = machine_changes
            best_l1 = l1_shift
            feasible_count += 1
            print(f"  Found feasible: makespan={makespan}, mc={machine_changes}, L1={l1_shift}")
        elif not valid and makespan <= MAX_MAKESPAN:
            # Check if only L1 issue
            pass

    print(f"\nTotal combinations checked: {count}")
    print(f"Feasible solutions found: {feasible_count}")

    return best_schedule, best_makespan, best_mc, best_l1


# Also try a smarter approach with priority dispatching
def schedule_with_priorities(machine_choices, priority_rule="SPT"):
    """
    Schedule using priority-based dispatching.
    priority_rule: SPT (shortest processing time), LPT, etc.
    """
    dur = {}
    for job in range(NUM_JOBS):
        for op in range(3):
            m = machine_choices[(job, op)]
            d = get_duration(job, op, m)
            if d is None:
                return None
            dur[(job, op)] = d

    machine_intervals = {m: [] for m in range(NUM_MACHINES)}
    schedule = []
    scheduled = set()
    job_end = {j: 0 for j in range(NUM_JOBS)}

    # Place frozen operations
    for key in frozen:
        job, op = key
        bl = baseline_lookup[key]
        entry = {
            "job": job, "op": op, "machine": bl["machine"],
            "start": bl["start"], "end": bl["end"], "dur": bl["dur"]
        }
        schedule.append(entry)
        machine_intervals[bl["machine"]].append((bl["start"], bl["end"]))
        job_end[job] = max(job_end[job], bl["end"])
        scheduled.add(key)

    while len(scheduled) < 12:
        ready = []
        for job in range(NUM_JOBS):
            for op in range(3):
                if (job, op) in scheduled:
                    continue
                if op == 0 or (job, op - 1) in scheduled:
                    m = machine_choices[(job, op)]
                    d = dur[(job, op)]
                    earliest = 0
                    if op > 0:
                        for e in schedule:
                            if e["job"] == job and e["op"] == op - 1:
                                earliest = e["end"]
                                break
                    start = find_earliest_slot(m, earliest, d, machine_intervals[m])
                    ready.append((job, op, m, d, start))

        if not ready:
            break

        # Sort by priority
        if priority_rule == "SPT":
            ready.sort(key=lambda x: (x[4], x[3]))  # earliest start, then shortest
        elif priority_rule == "EST":
            ready.sort(key=lambda x: x[4])
        elif priority_rule == "LPT":
            ready.sort(key=lambda x: (x[4], -x[3]))

        # Schedule the best ready operation
        job, op, m, d, start = ready[0]
        end = start + d
        entry = {"job": job, "op": op, "machine": m, "start": start, "end": end, "dur": d}
        schedule.append(entry)
        machine_intervals[m].append((start, end))
        machine_intervals[m].sort()
        scheduled.add((job, op))
        job_end[job] = max(job_end[job], end)

    if len(scheduled) != 12:
        return None
    return schedule


